<?php
declare(strict_types=1);
if (!defined('CWP_BOOT')) { http_response_code(404); exit; }
require_once CWP_CODE_ROOT.'/app/providers/registrar.php';
provider_settings_manager();
?>
<section class="workspace-card" id="registered-domains"><h2>Registered domains</h2>
<p>Read registered-domain identities from your 20i account, then assign each domain to its client. Hosting domain assignments are separate. Registration, renewal, expiry and nameserver changes are not confirmed by this list.</p>
<?php if(!provider_inventory_ready()): ?><p>Prepare hosting inventory above first.</p>
<?php else: try { $registrarReady=provider_registrar_ready(); } catch(RuntimeException $e) { if($e instanceof PDOException)throw $e;echo '<p class="notice error">'.esc($e->getMessage()).'</p></section>';return; } ?>
<?php if(!$registrarReady): ?><form method="post"><?php admin_action('provider_inventory_registrar_prepare');admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"'); ?><button class="btn gold">Prepare registered domains</button></form>
<?php elseif($record):
    $registrarProfile=provider_settings_load($profileId);$registrarLatest=provider_registrar_latest($profileId);$registrarFresh=provider_registrar_fresh($registrarProfile,$registrarLatest);
    $registrarRows=$registrarLatest&&in_array($registrarLatest['state'],['complete','partial'],true)?provider_registrar_rows($registrarLatest['id']):[];
    $registrarClients=provider_inventory_clients();$registrarLinks=all('SELECT l.*,c.name AS client_name FROM '.table('provider_registrar_links').' l JOIN '.table('studio_clients').' c ON c.id=l.client_id WHERE l.profile_id=? ORDER BY l.domain',[$profileId]);
    $registrarPage=max(1,min(410,(int)($_GET['registrar_page']??1)));$registrarShown=array_slice($registrarRows,($registrarPage-1)*20,20);
?>
<form method="post"><?php admin_action('provider_inventory_registrar_refresh'); ?><input type="hidden" name="profile_id" value="<?=esc($profileId)?>"><input type="hidden" name="revision" value="<?=(int)$record['revision']?>"><?php admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"'); ?><button class="btn outline">Refresh registered domains</button></form>
<?php if($registrarLatest): ?><p>Latest attempt: <?=esc($registrarLatest['state']??'unfinished')?> · <?=esc($registrarLatest['started_at'])?> UTC. <?=(int)($registrarLatest['package_count']??0)?> returned identities. This list may not include every domain in your account.</p><?php endif; ?>
<?php if(!$registrarFresh): ?><p class="notice">Refresh and confirm the returned list before assigning domains. A partial, failed, unfinished or older observation cannot authorize an assignment.</p><?php endif; ?>
<?php foreach($registrarShown as $registered): ?><article class="workspace-card"><h3><?=esc($registered['domain'])?></h3><p>20i domain #<?=(int)$registered['domain_id']?></p>
<?php if($registrarFresh): ?><form method="post"><?php admin_action('provider_inventory_registrar_link'); ?><input type="hidden" name="profile_id" value="<?=esc($profileId)?>"><input type="hidden" name="revision" value="<?=(int)$record['revision']?>"><input type="hidden" name="refresh_id" value="<?=esc($registrarLatest['id'])?>"><input type="hidden" name="domain_id" value="<?=(int)$registered['domain_id']?>"><label>Client<select name="client_id" required><option value="">Choose a client</option><?php foreach($registrarClients as $choice): ?><option value="<?=(int)$choice['id']?>"><?=esc($choice['name'])?></option><?php endforeach; ?></select></label><?php admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"'); ?><button class="btn outline">Assign registered domain</button></form><?php endif; ?></article><?php endforeach; ?>
<nav class="button-row" aria-label="Registered domain pages"><?php if($registrarPage>1): ?><a class="btn outline" href="<?=esc(admin_url('provider-settings',['registrar_page'=>$registrarPage-1]))?>#registered-domains">Previous domains</a><?php endif; ?><?php if(count($registrarRows)>$registrarPage*20): ?><a class="btn outline" href="<?=esc(admin_url('provider-settings',['registrar_page'=>$registrarPage+1]))?>#registered-domains">More domains</a><?php endif; ?></nav>
<h3>Client assignments</h3>
<?php foreach($registrarLinks as $assignment): ?><article class="workspace-card"><h4><?=esc($assignment['domain'])?> · <?=esc($assignment['client_name'])?></h4><p>Assignment version <?=(int)$assignment['revision']?>. Removing this assignment does not cancel or transfer the domain.</p>
<form method="post"><?php admin_action('provider_inventory_registrar_unlink'); ?><input type="hidden" name="link_id" value="<?=esc($assignment['id'])?>"><input type="hidden" name="link_revision" value="<?=(int)$assignment['revision']?>"><?php admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"'); ?><button class="btn outline">Remove assignment</button></form>
<?php if($registrarFresh): ?><form method="post"><?php admin_action('provider_inventory_registrar_relink'); ?><input type="hidden" name="link_id" value="<?=esc($assignment['id'])?>"><input type="hidden" name="link_revision" value="<?=(int)$assignment['revision']?>"><input type="hidden" name="revision" value="<?=(int)$record['revision']?>"><input type="hidden" name="refresh_id" value="<?=esc($registrarLatest['id'])?>"><?php admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"'); ?><button class="btn outline">Confirm current assignment</button></form><?php endif; ?></article><?php endforeach; ?>
<h3>Recent registered-domain reads</h3><ul><?php foreach(array_slice(provider_inventory_history($profileId,1,\CajunWebPro\Foundation\TwentyIInventory\InventoryRead::DOMAINS_LIST),0,20) as $read): ?><li><?=esc($read['started_at'])?> UTC · <?=esc($read['state'])?> · <?=(int)$read['package_count']?> identities</li><?php endforeach; ?></ul>
<?php endif; endif; ?></section>
